"""Small resilient client for the order service. Working file, not a deliverable."""
import json
import time
import urllib.request
import urllib.error

BASE = "http://localhost:8080"
LOG_PATH = "/tmp/recon_work/events.log"

_token = None
_token_requests = 0  # requests made with the current token (for observation only)


def _log(msg):
    line = f"{time.strftime('%H:%M:%S')} {msg}"
    with open(LOG_PATH, "a") as fh:
        fh.write(line + "\n")
    print(line, flush=True)


def _raw(method, path, token=None, timeout=30):
    """Return (status, headers_dict, body_text). Never raises on HTTP error codes."""
    req = urllib.request.Request(BASE + path, method=method, data=b"" if method == "POST" else None)
    if token:
        req.add_header("Authorization", f"Bearer {token}")
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return resp.status, dict(resp.headers.items()), resp.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers.items()), e.read().decode("utf-8", "replace")


def new_token():
    global _token, _token_requests
    while True:
        status, headers, body = _raw("POST", "/token")
        if status == 200:
            try:
                _token = json.loads(body)["token"]
                _token_requests = 0
                _log(f"new token {_token}")
                return _token
            except Exception as exc:  # malformed -> retry
                _log(f"token parse failure {exc!r} body={body[:200]!r}")
        else:
            _log(f"token endpoint status={status} headers={headers} body={body[:300]!r}")
            wait = _retry_after(headers, body)
            time.sleep(wait if wait is not None else 1)


def _retry_after(headers, body):
    """Seconds the server asked us to wait, from the Retry-After header or the JSON body; else None."""
    for k, v in headers.items():
        if k.lower() == "retry-after":
            try:
                return float(v)
            except ValueError:
                return None
    try:
        data = json.loads(body)
    except Exception:
        return None
    if isinstance(data, dict):
        for key in ("retry_after", "retry_after_seconds", "retry_after_s", "wait", "wait_seconds"):
            if key in data:
                try:
                    return float(data[key])
                except (TypeError, ValueError):
                    return None
    return None


def get_json(path, max_attempts=200):
    """GET an authenticated JSON path. Retries on throttling, expired tokens and server errors.

    Returns (status, parsed_json). A 404 is returned to the caller (it is a documented answer);
    every other non-200 outcome is retried.
    """
    global _token, _token_requests
    attempt = 0
    while attempt < max_attempts:
        attempt += 1
        if _token is None:
            new_token()
        try:
            status, headers, body = _raw("GET", path, token=_token)
        except Exception as exc:  # network hiccup -> retry
            _log(f"{path} attempt {attempt}: transport error {exc!r}")
            time.sleep(1)
            continue
        _token_requests += 1
        if status == 200:
            try:
                return 200, json.loads(body)
            except Exception as exc:
                _log(f"{path} attempt {attempt}: 200 but unparseable body {exc!r} body={body[:200]!r}")
                time.sleep(0.5)
                continue
        if status == 404:
            return 404, _safe_json(body)
        # Everything else: log it in full so unexpected behaviours are visible.
        _log(f"{path} attempt {attempt}: status={status} after {_token_requests} reqs on token "
             f"headers={headers} body={body[:300]!r}")
        if status == 429:
            wait = _retry_after(headers, body)
            if wait is None:
                raise RuntimeError(f"429 without a recognisable wait time: {headers} {body[:300]!r}")
            time.sleep(wait)
            continue
        if status in (401, 403):
            _token = None  # fetch a fresh one on the next loop
            continue
        # 5xx and anything else: brief pause, repeat the request
        wait = _retry_after(headers, body)
        time.sleep(wait if wait is not None else 1)
    raise RuntimeError(f"gave up on {path} after {max_attempts} attempts")


def _safe_json(body):
    try:
        return json.loads(body)
    except Exception:
        return body

