cd /tmp/recon_work && python3 -I - <<'EOF'
import glob, json
from datetime import datetime, timezone, timedelta
START = datetime(2025,3,1,tzinfo=timezone.utc); END = datetime(2025,6,1,tzinfo=timezone.utc)
def utc(ts):
    return datetime.fromisoformat(ts[:-1]+"+00:00" if ts.endswith("Z") else ts).astimezone(timezone.utc)
seen = {}
for fp in sorted(glob.glob("pages/page_*.json")):
    for it in json.load(open(fp))["items"]:
        seen.setdefault(it["id"], it)
rows = []
for it in seen.values():
    if it["status"] != "shipped": continue
    u = utc(it["placed_at"])
    near = min(abs(u - START), abs(u - END)) <= timedelta(hours=36)
    if near:
        rows.append((u, it))
rows.sort(key=lambda r: r[0])
print(f"{'id':9} {'placed_at':26} {'utc':20} in_window  local_date_in_range")
for u, it in rows:
    inw = START <= u < END
    loc = "2025-03-01" <= it["placed_at"][:10] <= "2025-05-31"
    flag = "  <-- differs from local-date filter" if inw != loc else ""
    print(f"{it['id']:9} {it['placed_at']:26} {u.strftime('%Y-%m-%dT%H:%M:%SZ'):20} {str(inw):9}  {loc}{flag}")
EOF

